@Override
protected Subtitle decode(byte[] bytes, int length, boolean reset) {
  try {
    parsableByteArray.reset(bytes, length);
    int textLength = parsableByteArray.readUnsignedShort();
    if (textLength == 0) {
      return Tx3gSubtitle.EMPTY;
    }
    String cueText = parsableByteArray.readString(textLength);
    return new Tx3gSubtitle(new Cue(cueText));
  } catch (ArrayIndexOutOfBoundsException | IllegalArgumentException e) {
    // Handle the exception, log or take appropriate action
    e.printStackTrace(); // Or a more sophisticated error handling
    return Tx3gSubtitle.EMPTY; // Or another suitable fallback
  }
}
